function pick(id,draw=true){S.picked=id;S.note='';const d=catalog().find(m=>m.id===id)?.data;S.choices=Object.fromEntries((d?.posOptions118||[]).map(g=>[g.id,g.min>0?g.options.filter(o=>o.available!==false).slice(0,g.min).map(o=>o.id):[]]));if(draw)render()}
function optionAvailable(o){if(o.available===false)return false;if(S.sample)return true;return(o.recipe||[]).every(r=>{const ingredient=S.ingredients.find(i=>i.id===r.itemId)?.data;return ingredient?.inventoryItemId118&&stock(ingredient.inventoryItemId118)>=n(r.quantity)*n(ingredient.inventoryFactor118||1)})}
function recipeUsage124(data){const uses={};function expand(id,quantity,seen=[]){if(seen.includes(id)||seen.length>12)throw Error('Recipe cycle');const d=S.menu.find(m=>m.id===id)?.data;if(!d)throw Error('Recipe is unavailable');if(d.itemType==='bundle')return(d.recipe||[]).flatMap(r=>expand(r.itemId,n(r.quantity)*quantity,[...seen,id]));return(d.recipe||[]).map(r=>({...r,quantity:n(r.quantity)*quantity}))}for(const line of data.lines||[]){const d=S.menu.find(m=>m.id===line.menuId)?.data;if(!d)throw Error('Recipe is unavailable');let recipe=expand(line.menuId,1);for(const g of d.posOptions118||[]){const selected=line.choices?.[g.id]||[];if(selected.length)recipe=recipe.filter(r=>!(g.replaces||[]).includes(r.itemId));for(const id of selected){const o=g.options.find(o=>o.id===id);if(!o)throw Error('Recipe choice is unavailable');recipe.push(...(o.recipe||[]))}}for(const r of recipe){const ing=S.ingredients.find(i=>i.id===r.itemId)?.data;if(!ing?.inventoryItemId118)throw Error('Link the selected ingredients to Inventory before offline payment');const quantity=n(r.quantity)*n(ing.inventoryFactor118??1)*n(line.quantity);if(!(quantity>0))throw Error('Invalid ingredient conversion');uses[ing.inventoryItemId118]=(uses[ing.inventoryItemId118]||0)+quantity}}return uses}
