async function rpc(name,args){const out=await ojmDb.rpc(name,args);if(out.error)throw Error(out.error.message);return out.data}
function offlineOwner(){return liveProfile?.id}
async function pending(){S.offlineQueue=await posOffline119.queue(offlineOwner());return S.offlineQueue}
function overlayPending(){for(const entry of S.offlineQueue){const order={...entry.order,offlinePending:true};S.orders=[order,...S.orders.filter(o=>o.id!==order.id)]}}
async function syncPending(){if(S.sample||!navigator.onLine||!offlineOwner())return;const owner=offlineOwner(),epoch=sessionEpoch121,valid=()=>owner===offlineOwner()&&epoch===sessionEpoch121;const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;S.syncError='';for(const entry of entries){if(!valid())return;try{await rpc('pos_order118',{p_id:entry.order.id,p_version:entry.order.version||0,p_action:entry.action,p_data:entry.data});if(!valid())return;await posOffline119.remove(owner,entry.order.id)}catch(e){if(valid())S.syncError='Sync stopped: '+e.message;break}}const left=await posOffline119.queue(owner);if(valid())S.offlineQueue=left}
async function load(){if(S.busy||!offlineOwner())return;const owner=offlineOwner(),epoch=sessionEpoch121,valid=()=>owner===offlineOwner()&&epoch===sessionEpoch121;S.busy=true;S.error='';render();try{if(navigator.onLine)await syncPending();if(!valid())return;const data=await rpc('pos_snapshot118',{});if(!valid())return;if(!data||!Array.isArray(data.orders))throw Error('POS database setup is required. Apply the separate v118 POS SQL.');Object.assign(S,data,{loaded:true,owner,offline:false});await posOffline119.saveSnapshot(owner,data);if(!valid())return;navigator.storage?.persist?.().catch(()=>{});const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;overlayPending();const m=menuStore108.state;Object.assign(m,{menu:S.menu,ingredients:S.ingredients,items:S.items,categories:S.categories,moves:[...S.moves,...virtualMoves()],owner,loaded:true});if(!S.picked||!catalog().some(x=>x.id===S.picked))pick(catalog()[0]?.id,false)}catch(e){if(!valid())return;const connectionFailure=(!navigator.onLine||/failed to fetch|networkerror|network request failed|load failed/i.test(e.message))&&!/permission|access required|unauthorized|inactive/i.test(e.message);const cached=connectionFailure?await posOffline119.getSnapshot(owner).catch(()=>null):null;if(!valid())return;if(cached){Object.assign(S,cached.data,{loaded:true,owner,offline:true});const entries=await posOffline119.queue(owner);if(!valid())return;S.offlineQueue=entries;overlayPending();if(!S.picked||!catalog().some(x=>x.id===S.picked))pick(catalog()[0]?.id,false);Object.assign(menuStore108.state,{menu:S.menu,ingredients:S.ingredients,items:S.items,categories:S.categories,moves:[...S.moves,...virtualMoves()],owner,loaded:true});S.error='Offline: using the last saved Menu and shift. Sales remain on this device until synced.'}else{S.loaded=false;S.error=connectionFailure?'No offline copy is ready on this device. Connect once while signed in to prepare POS.':e.message;showCenterStatus(S.error,true)}}finally{if(valid()){S.busy=false;render()}}}

