function add(){if(!restaurantCan('pos','sell'))throw Error('Sales access required');const record=catalog().find(r=>r.id===S.picked);if(!record)return;const d=record.data;let price=n(d.price),names=[];if(d.posCustom118&&(d.posOptions118||[]).filter(g=>g.id!=='wellness').every(g=>!(S.choices[g.id]||[]).length))throw Error('Select at least one sauce, veggie, or protein.');for(const g of d.posOptions118||[]){const choices=S.choices[g.id]||[];if(choices.length<n(g.min)||choices.length>n(g.max))throw Error('Select '+g.min+'–'+g.max+' choices for '+g.name);price+=groupPrice(g,choices);for(const id of choices){const o=g.options.find(o=>o.id===id);if(!o||!optionAvailable(o))throw Error('Selected option is unavailable');names.push(o.name)}}const line={menuId:record.id,name:d.name,photoData:d.photoData,photo118:d.photo118,quantity:S.editLine!=null?draft.data.lines[S.editLine].quantity:1,unitPrice:price,choices:structuredClone(S.choices),options:names,note:S.note};if(S.editLine!=null)draft.data.lines[S.editLine]=line;else draft.data.lines.push(line);S.editLine=null;render()}
async function save(action='save',extra={}){const saveOwner=offlineOwner(),saveEpoch=sessionEpoch121;if(!restaurantCan('pos','sell'))throw Error('Sales access required');if(!draft.data.lines.length)throw Error('Add an item first');if(action==='pay'&&!S.sample&&draft.data.lines.some(l=>catalog().find(r=>r.id===l.menuId)?.data.posSetupPending120))throw Error('This menu item needs its recipe and Inventory links reviewed before payment. Save the order unpaid.');if(total(draft.data).discount>total(draft.data).subtotal)throw Error('Discount exceeds subtotal');await task(action==='pay'?'Recording payment and stock…':'Saving order…',async()=>{let result;if(S.sample){result={...structuredClone(draft),number:draft.number||Math.max(1053,...S.orders.map(o=>o.number))+1,status:action==='pay'?'paid':'unpaid',created_at:draft.created_at||new Date().toISOString(),paid_at:action==='pay'?new Date().toISOString():null,data:{...structuredClone(draft.data),...extra,...total(draft.data)}};S.orders=[result,...S.orders.filter(o=>o.id!==result.id)]}else{const offline=async()=>{const captureOwner=offlineOwner(),captureEpoch=sessionEpoch121,usage=action==='pay'?recipeUsage124(draft.data):{};if(action==='pay')for(const [id,q] of Object.entries(usage))if(q>stock(id))throw Error('Insufficient stock on this device');if(action==='pay'&&!S.shifts.some(x=>x.cashier===liveProfile?.id&&!x.closed_at))throw Error('Open your shift online before accepting offline payments.');const existing=S.offlineQueue.find(x=>x.order.id===draft.id);result={...structuredClone(draft),number:draft.number||'LOCAL',status:action==='pay'?'paid':'unpaid',created_at:draft.created_at||new Date().toISOString(),paid_at:action==='pay'?new Date().toISOString():null,offlinePending:true,data:{...structuredClone(draft.data),...extra,...total(draft.data),cashier:currentUser()}};await posOffline119.save(captureOwner,result,action,{...draft.data,...extra,offlineUsage124:usage,offlineNonce:uuid(),...(action==='pay'?{offlineCapturedAt:result.paid_at,offlineTotal:result.data.total}:{})});if(captureOwner!==offlineOwner()||captureEpoch!==sessionEpoch121)throw Error('Account changed during local capture');await pending();S.orders=[result,...S.orders.filter(o=>o.id!==result.id)];S.offline=true};if(S.offline||!navigator.onLine)await offline();else try{result=await rpc('pos_order118',{p_id:draft.id,p_version:draft.version||0,p_action:action,p_data:{...draft.data,...extra}});if(saveOwner!==offlineOwner()||saveEpoch!==sessionEpoch121)return;await load()}catch(e){if(saveOwner!==offlineOwner()||saveEpoch!==sessionEpoch121)return;if(!navigator.onLine||/failed to fetch|networkerror|network request failed|load failed/i.test(e.message))await offline();else throw e}}if(saveOwner!==offlineOwner()||saveEpoch!==sessionEpoch121)return;draft=structuredClone(result);S.selected=result.id;showCenterStatus(S.sample?'Sample order updated. No live records changed.':result.offlinePending?'Saved on this device. Pending sync before shift close.':action==='pay'?'Payment recorded and stock updated.':'Order saved unpaid.');if(action==='pay'){print(result);fresh();S.sub='Receipts';S.selected=result.id}else{S.sub='Open Orders'}})}
function dialog(title,body,submit){const promise=ui108.modal(title,body,[]);const root=$('.ui-overlay108:last-child');root.querySelector('.ui-dialog108').classList.add('pos-dialog118');if(submit){const f=root.querySelector('form');f.onsubmit=async e=>{e.preventDefault();if(!f.reportValidity())return;const b=f.querySelector('[type=submit]');b.disabled=true;try{await submit(Object.fromEntries(new FormData(f)),f);root.resolve108(true)}catch(e){let out=f.querySelector('.form-error118');if(!out){out=document.createElement('p');out.className='form-error118';out.setAttribute('role','alert');f.append(out)}out.textContent=e.message;showCenterStatus(e.message,true)}finally{b.disabled=false}}}return root}
function field(label,name,value='',type='text',attrs=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function charge(){
 if(!S.sample&&(S.offline||!navigator.onLine)&&!S.shifts.some(x=>x.cashier===liveProfile?.id&&!x.closed_at))throw Error('Open your shift online before accepting offline payments.');
 if(S.sub!=='New Order'){const o=selectedOrder();if(!o)return;draft=structuredClone(o)}
 const t=total(draft.data);if(!draft.data.lines.length)throw Error('Add an item first');
 const root=dialog('Confirm payment',`<form><strong>Total ${money(t.total)}</strong><label>Payment method<select name="payment">${S.config.methods.map(v=>'<option>'+esc(v)+'</option>').join('')}</select></label>${field('Cash received (LAK)','tendered',t.total,'number','min="0" step="any"')}${field('Bank / QR transaction reference','paymentReference')}<p>Confirm the amount and method before recording this sale. Bank and QR transfers are confirmed manually.</p><div class="pos-payment-preview118">${receipt({...draft,status:'unpaid'},false)}</div><button type="submit">Confirm & Print</button></form>`,async d=>{await save('pay',{...d,confirmed:true})});
 const method=root.querySelector('[name="payment"]'),reference=root.querySelector('[name="paymentReference"]'),cash=root.querySelector('[name="tendered"]');
 function fields(){const bank=method.value!=='Cash';reference.required=bank;reference.closest('label').hidden=!bank;cash.required=!bank;cash.closest('label').hidden=bank}method.addEventListener('change',fields);fields();
}

function print(o,kitchen=false,pdf=false){const frame=document.createElement('iframe');frame.style.cssText='position:fixed;width:0;height:0;border:0';document.body.append(frame);const doc=frame.contentDocument;doc.open();doc.write(`<!doctype html><html><head><title>${kitchen?'Kitchen':'Receipt'}-${o.number||'preview'}</title><style>@page{size:${n(S.config.receiptWidth)||80}mm auto;margin:4mm}body{margin:0;font:12px Georgia;color:#111}.receipt118{max-width:100%}.receipt118 header{text-align:center}.receipt118 img{width:40mm;height:20mm;object-fit:contain}.receipt-row118{display:flex;justify-content:space-between;gap:8px;margin:7px 0}hr{border:0;border-top:1px dashed #666}.receipt-foot118{text-align:center}article:not(:last-child){break-after:page}h3{font-size:15px}</style></head><body>${Array.isArray(o)?o.map(r=>receipt(r,kitchen)).join(''):receipt(o,kitchen)}</body></html>`);doc.close();frame.contentWindow.addEventListener('afterprint',()=>frame.remove(),{once:true});setTimeout(()=>{frame.contentWindow.focus();frame.contentWindow.print()},350);if(pdf)showCenterStatus('Choose Save as PDF in the print dialog.')}
function settings(){if(!restaurantCan('pos','manage'))throw Error('Administrator access required');const c=S.config;dialog('POS settings',`<form><h3>Payments & discounts</h3>${['Cash','BCEL QR','Bank'].map(m=>`<label class="check"><input type="checkbox" name="methods" value="${m}" ${c.methods.includes(m)?'checked':''}>${m}</label>`).join('')}${field('Cashier discount limit (%)','discountLimit',c.discountLimit,'number','min="0" max="100" required')}<h3>Legacy cashier list</h3><p>Restaurant sign-in and permissions are managed in Settings → Users & Access. This legacy list does not grant restaurant access.</p>${(typeof liveProfiles!=='undefined'?liveProfiles:[]).filter(p=>p.role!=='admin').map(p=>`<label class="check"><input type="checkbox" name="cashiers" value="${esc(p.id)}" ${c.cashiers.includes(p.id)?'checked':''}>${esc(p.full_name||p.email)}</label>`).join('')||'<p>No additional staff profiles loaded.</p>'}<h3>Printing</h3><label>Receipt paper<select name="receiptWidth"><option value="80" ${n(c.receiptWidth)===80?'selected':''}>80 mm</option><option value="58" ${n(c.receiptWidth)===58?'selected':''}>58 mm</option></select></label>${field('Receipt footer','receiptFooter',c.receiptFooter)}<p>Choose your receipt or kitchen printer in the browser print dialog. Silent hardware printing is not connected.</p><button type="submit">Save settings</button></form>`,async(d,f)=>{const values={...c,...d,discountLimit:n(d.discountLimit),receiptWidth:n(d.receiptWidth),methods:new FormData(f).getAll('methods'),cashiers:new FormData(f).getAll('cashiers')};if(!values.methods.length)throw Error('Enable at least one payment method');if(S.sample)S.config=values;else{await rpc('pos_manage118',{p_action:'config',p_data:values,p_version:S.configVersion});await load()}showCenterStatus(S.sample?'Sample settings updated.':'POS settings saved.')})}
function shift(action){const closing=action==='close',cash=action==='cash';if(!S.sample&&(closing||cash)&&(!navigator.onLine||S.offline||S.offlineQueue.length))throw Error(S.offlineQueue.length?'Sync all pending sales before cash movement or closing the shift.':'Connect to the internet before changing the shift.');if(!S.sample&&action==='open'&&(!navigator.onLine||S.offline))throw Error('Connect once to open a shift before taking offline payments.');dialog(closing?'Close shift':cash?'Cash in / out':'Open shift',`<form>${field(closing?'Counted cash (LAK)':cash?'Amount (positive = in, negative = out)':'Opening float (LAK)','amount',0,'number',(cash?'':'min="0" ')+'step="any" required')}${cash?field('Reason / reference','reason','','text','required minlength="3"'):''}${closing?'<p>The counted cash and variance will be preserved in shift history.</p>':''}<button type="submit">${closing?'Close shift':'Save'}</button></form>`,async d=>{if(S.sample){const s=S.shifts.find(s=>!s.closed_at);if(action==='open'){if(s)throw Error('A sample shift is already open');S.shifts.push({id:uuid(),cashier:liveProfile.id,opening:n(d.amount),opened_at:new Date().toISOString()})}else if(!s)throw Error('Open a shift first');else if(cash)S.cash.push({id:uuid(),shift_id:s.id,amount:n(d.amount),reason:d.reason});else{Object.assign(s,{closed_at:new Date().toISOString(),counted:n(d.amount),expected:shiftExpected(s)})}}else await rpc('pos_manage118',{p_action:action,p_data:d,p_version:0});if(!S.sample)await load();showCenterStatus('Shift updated.');render()})}
function refund(cancel=false){const o=selectedOrder();if(!o)return;if(!restaurantCan('pos',cancel?'void':'refund'))throw Error('Administrator approval required');dialog(cancel?'Cancel unpaid order':'Refund paid order',`<form><p>${cancel?'Cancel':'Record a full refund for'} #${o.number} · ${money(o.data.total)}</p>${field('Reason','reason','','text','required minlength="3"')}${cancel?'':'<label class="check"><input type="checkbox" name="restock">Return all consumed ingredients to usable stock</label><p>Leave unchecked for prepared food that cannot be reused. Confirm the actual refund in your payment system separately.</p>'}<button type="submit">${cancel?'Cancel order':'Confirm refund'}</button></form>`,async(d,f)=>{if(S.sample){o.status=cancel?'cancelled':'refunded';o.refunded_at=new Date().toISOString()}else await rpc('pos_order118',{p_id:o.id,p_version:o.version,p_action:cancel?'cancel':'refund',p_data:{reason:d.reason,restock:!!f.elements.restock?.checked}});if(!S.sample)await load();showCenterStatus(cancel?'Order cancelled.':'Refund recorded.');render()})}
function options(){if(!admin()&&!S.sample)throw Error('Administrator access required');let selected=S.picked||catalog()[0]?.id;if(!selected)throw Error('Add a menu item first');const root=dialog('Customization options','<div id="posOptionsEditor118"></div>');const host=root.querySelector('#posOptionsEditor118');let groups,nonstock;
function draw(){const record=catalog().find(r=>r.id===selected);groups=structuredClone(record.data.posOptions118||[]);nonstock=record.data.posNoStock118===true;paint()}
function paint(){host.innerHTML=`<form><label>Menu item<select name="menu">${catalog().map(r=>`<option value="${r.id}" ${r.id===selected?'selected':''}>${esc(r.data.name)}</option>`).join('')}</select></label><label class="check"><input name="nonstock" type="checkbox" ${nonstock?'checked':''}>Non-stock item (no recipe or inventory consumption)</label><p>Required groups set a minimum above zero. Substitutions replace the specified base-recipe ingredient when a choice is selected. Quantities use the ingredient’s recipe unit.</p>${groups.map((g,i)=>`<section class="choice-edit118" data-group-edit118="${i}"><div class="fields118">${field('Group name','gname'+i,g.name)}${field('Minimum choices','gmin'+i,g.min,'number','min="0" max="20" required')}${field('Maximum choices','gmax'+i,g.max,'number','min="1" max="20" required')}${g.included!=null?field('Included choices','gincluded'+i,g.included,'number','min="0" max="20" required')+field('Each extra choice (LAK)','gextra'+i,g.extraPrice||0,'number','min="0" step="any" required'):''}<label>Replaces base ingredient<select name="replace${i}"><option value="">Add-on only</option>${S.ingredients.map(r=>`<option value="${r.id}" ${g.replaces?.includes(r.id)?'selected':''}>${esc(r.data.name)}</option>`).join('')}</select></label></div>${g.options.map((o,j)=>`<div class="option-grid118">${field('Choice','oname'+i+'_'+j,o.name,'text','required')}${field('Extra LAK','oprice'+i+'_'+j,o.price||0,'number','min="0" step="any" required')}<label>Ingredient<select name="oing${i}_${j}"><option value="">No additional ingredient</option>${S.ingredients.map(r=>`<option value="${r.id}" ${o.recipe?.[0]?.itemId===r.id?'selected':''}>${esc(r.data.name)}</option>`).join('')}</select></label>${field('Quantity','oqty'+i+'_'+j,o.recipe?.[0]?.quantity||0,'number','min="0" step="any"')}<button type="button" data-remove-option118="${i},${j}" aria-label="Remove option">×</button></div><label class="check"><input type="checkbox" name="available${i}_${j}" ${o.available!==false?'checked':''}>Available</label>`).join('')}<button type="button" data-add-option118="${i}">Add choice</button> <button type="button" data-remove-group118="${i}">Remove group</button></section>`).join('')}<div class="pos-actions118"><button type="button" data-add-group118>Add option group</button><button type="submit">Save customizations</button></div></form>`;
const f=host.querySelector('form');f.elements.menu.onchange=()=>{selected=f.elements.menu.value;draw()};function capture(){nonstock=f.elements.nonstock.checked;groups.forEach((g,i)=>{g.name=f.elements['gname'+i].value;g.min=n(f.elements['gmin'+i].value);g.max=n(f.elements['gmax'+i].value);if(g.included!=null){g.included=n(f.elements['gincluded'+i].value);g.extraPrice=n(f.elements['gextra'+i].value)}g.replaces=f.elements['replace'+i].value?[f.elements['replace'+i].value]:[];g.options.forEach((o,j)=>{o.name=f.elements['oname'+i+'_'+j].value;o.price=n(f.elements['oprice'+i+'_'+j].value);o.available=f.elements['available'+i+'_'+j].checked;const ingredient=f.elements['oing'+i+'_'+j].value,quantity=n(f.elements['oqty'+i+'_'+j].value);o.recipe=ingredient?[{itemId:ingredient,quantity}]:[]})})}
host.querySelector('[data-add-group118]').onclick=()=>{capture();groups.push({id:uuid(),name:'New group',min:0,max:1,replaces:[],options:[]});paint()};host.querySelectorAll('[data-add-option118]').forEach(b=>b.onclick=()=>{capture();groups[n(b.dataset.addOption118)].options.push({id:uuid(),name:'New option',price:0,recipe:[]});paint()});host.querySelectorAll('[data-remove-option118]').forEach(b=>b.onclick=()=>{capture();const [i,j]=b.dataset.removeOption118.split(',').map(Number);groups[i].options.splice(j,1);paint()});host.querySelectorAll('[data-remove-group118]').forEach(b=>b.onclick=()=>{capture();groups.splice(n(b.dataset.removeGroup118),1);paint()});f.onsubmit=async e=>{e.preventDefault();capture();try{for(const g of groups){if(!g.name.trim()||g.min>g.max||g.max>g.options.length||g.min<0||(g.included!=null&&(g.included>g.max||g.extraPrice<0))||g.options.some(o=>!o.name.trim()||o.recipe.some(r=>r.quantity<=0)))throw Error('Review group limits, option names and ingredient quantities')}const record=catalog().find(r=>r.id===selected),data={...record.data,posOptions118:groups,posNoStock118:nonstock};if(S.sample)record.data=data;else{await menuStore108.save('menu',data,record);await load()}pick(selected,false);root.resolve108(true);showCenterStatus(S.sample?'Sample customizations updated.':'Customizations saved to Menu.');render()}catch(e){showCenterStatus(e.message,true)}}}draw()}
function links(){if(!admin()&&!S.sample)throw Error('Administrator access required');if(S.sample){dialog('Ingredient links','<p>In Live operation, each Menu ingredient is linked to an Inventory item, with an explicit unit conversion. The selected base, protein, toppings and extras determine the stock used.</p><p>Switch to Live operation to configure your actual ingredients.</p>');return}dialog('Menu ingredient → Inventory',`<form><p>Enter the Inventory quantity consumed by one recipe unit. Example: ingredient unit g and Inventory unit kg → factor 0.001.</p><table><thead><tr><th>Menu ingredient</th><th>Inventory item</th><th>Factor</th></tr></thead><tbody>${S.ingredients.map((r,i)=>`<tr><td>${esc(r.data.name)} (${esc(r.data.unit)})</td><td><select name="item${i}"><option value="">Not linked</option>${S.items.map(t=>`<option value="${t.id}" ${r.data.inventoryItemId118===t.id?'selected':''}>${esc(t.data.name)} (${esc(t.data.unit)})</option>`).join('')}</select></td><td><input aria-label="Conversion factor for ${esc(r.data.name)}" name="factor${i}" type="number" min="0.000001" step="any" value="${n(r.data.inventoryFactor118||1)}" required></td></tr>`).join('')}</tbody></table><button type="submit">Save ingredient links</button></form>`,async d=>{let saved=0;try{for(const [i,r] of S.ingredients.entries()){const id=d['item'+i],factor=n(d['factor'+i]);if(id===(r.data.inventoryItemId118||'')&&factor===n(r.data.inventoryFactor118||1))continue;await menuStore108.save('ingredients',{...r.data,inventoryItemId118:id,inventoryFactor118:factor},r);saved++}await load();showCenterStatus('Ingredient links saved.')}catch(e){throw Error(e.message+' '+saved+' links were saved; reload before retrying.')}})}
async function seed(){if(S.sample){showCenterStatus('The reference catalog is already loaded in samples. Switch to Live operation to copy it into Menu.');return}if(!admin())throw Error('Administrator access required');if(!await ui117.confirm('Add the eight reference menu items to Menu? Existing item codes are kept. Configure recipes, ingredient links and prices before live sales.'))return;await task('Adding reference catalog…',async()=>{let added=0;for(const r of sampleCatalog){if(S.menu.some(m=>m.data.code===r.data.code))continue;await menuStore108.save('menu',{...structuredClone(r.data),posNoStock118:false},null);added++}await load();showCenterStatus(added+' reference menu items added. Complete their recipes before charging.');S.tab='Management'})}
function exportRows(pdf=false){const from=$('#posExportFrom118')?.value,to=$('#posExportTo118')?.value;if(!from||!to||from>to)throw Error('Choose a valid export period');const rows=S.orders.filter(o=>o.paid_at&& (S.sample||new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Vientiane'}).format(new Date(o.paid_at))>=from&&new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Vientiane'}).format(new Date(o.paid_at))<=to));if(pdf){if(!rows.length)throw Error('No receipts for this period');return print(rows,false,true)}const safe=v=>'"'+(/^[=+@\-\t\r]/.test(String(v))?"'":'')+String(v??'').replaceAll('"','""')+'"',data=[['Receipt','Paid at','Status','Payment','Reference','Subtotal LAK','Discount LAK','Total LAK','Refunded at','Cashier','Sample'],...rows.map(o=>[o.number,o.paid_at,o.status,o.data.payment,o.data.paymentReference,o.data.subtotal,o.data.discount,o.data.total,o.refunded_at,o.data.cashier,S.sample?'YES':'NO'])].map(row=>row.map(safe).join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}));a.download='POS-'+(S.sample?'SAMPLE-':'')+from+'-'+to+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);showCenterStatus('Sales export downloaded.')}
async function action(action,b){if(b&&!actionPermission121(b))throw Error('This action is not included in your access.');const value=b?.dataset.value118,id=b?.dataset.id118,i=n(b?.dataset.index118);if(action==='tab'){S.visibleOrders=50;S.tab=value;if(value==='Sales')S.sub='New Order';S.query='';S.filter='All';render()}else if(action==='sub'){S.visibleOrders=50;S.sub=value;S.query='';S.filter='All';S.selected=null;render()}else if(action==='pick'){S.editLine=null;pick(id)}else if(action==='classification'){S.classification=value;S.visibleMenu=40;render()}else if(action==='category'){S.category=value;S.visibleMenu=40;render()}else if(action==='more-menu'){S.visibleMenu+=40;render()}else if(action==='filter'){S.filter=value;S.visibleOrders=50;render()}else if(action==='more'){S.visibleOrders+=50;render()}else if(action==='add'||action==='quick-add')add();else if(action==='remove'){draft.data.lines.splice(i,1);render()}else if(action==='qty'){const l=draft.data.lines[i];l.quantity=Math.max(1,Math.min(999,l.quantity+n(b.dataset.delta118)));render()}else if(action==='edit-line'){const l=draft.data.lines[i];pick(l.menuId,false);S.editLine=i;S.choices=structuredClone(l.choices);S.note=l.note;render()}else if(action==='save')await save();else if(action==='charge')charge();else if(action==='resume'){draft=structuredClone(selectedOrder());S.sub='New Order';render()}else if(action==='new'){if(draft.data.lines.length&&!await ui117.confirm('Start a new order? Save the current unpaid order first if you need it.'))return;fresh();S.tab='Sales';S.sub='New Order';render()}else if(['preview','print','pdf','kitchen'].includes(action)){let o=S.tab==='Sales'&&S.sub!=='New Order'?selectedOrder():draft;if(S.tab==='Management'&&(!o||!o.data.lines.length)){if(action==='preview')o={number:'Example',status:'unpaid',data:{lines:[sampleLine(0,1,true),sampleLine(5)],service:'Example layout',customer:'',discount:0,discountType:'amount'}};else o=selectedOrder()}if(!o||!o.data.lines.length)throw Error('Choose an order or receipt first.');if(action==='preview')dialog('Receipt preview',receipt(o));else print(o,action==='kitchen',action==='pdf')}else if(action==='refund')refund();else if(action==='cancel')refund(true);else if(action==='settings')settings();else if(action==='options')options();else if(action==='links')links();else if(action==='seed')await seed();else if(action==='menu')switchTab('menu-recipe');else if(action==='categories')switchTab('menu-categories');else if(action==='inventory')switchTab('inv-overview');else if(action==='shift-view'){S.tab='Overview';render()}else if(action==='sync'){await load()}else if(action==='reload'){if(S.sample){samples();render();showCenterStatus('Reference samples reset.')}else await load()}else if(action==='open-shift')shift('open');else if(action==='close-shift')shift('close');else if(action==='cash')shift('cash');else if(action==='export')exportRows();else if(action==='export-pdf')exportRows(true)}
function mount(){if($('#pos118'))return;const host=document.createElement('div');host.id='pos118';host.dataset.module='pos';host.className='tab-content';$('#menu-recipe').parentElement.append(host);/* The restaurant shell owns the sidebar; do not inject a second POS link. */samples();let lastPick=null;host.addEventListener('click',e=>{const b=e.target.closest('[data-pos118]');if(b?.dataset.pos118==='pick'){const now=performance.now(),id=b.dataset.id118;const double=e.detail>0&&lastPick&&lastPick.id===id&&now-lastPick.at<=500&&Math.hypot(e.clientX-lastPick.x,e.clientY-lastPick.y)<18;lastPick=double||e.detail===0?null:{id,at:now,x:e.clientX,y:e.clientY};if(double){action('quick-add',b).catch(err=>showCenterStatus(err.message,true))}else if(S.picked!==id||S.editLine!=null){action('pick',b).catch(err=>showCenterStatus(err.message,true))}return}lastPick=null;if(b){action(b.dataset.pos118,b).catch(e=>showCenterStatus(e.message,true));return}const tr=e.target.closest('[data-order118]');if(tr){S.selected=tr.dataset.order118;render()}});host.addEventListener('keydown',e=>{if(['Enter',' '].includes(e.key)&&e.target.matches('[data-order118]')){e.preventDefault();S.selected=e.target.dataset.order118;render()}});host.addEventListener('input',e=>{const t=e.target;if(t.matches('[data-search118]')){S.visibleOrders=50;S.visibleMenu=40;const pos=t.selectionStart;S.query=t.value;render();const input=host.querySelector('[data-search118]');input?.focus();input?.setSelectionRange(pos,pos)}if(t.matches('[data-item-note118]'))S.note=t.value;if(t.matches('[data-draft118]'))draft.data[t.dataset.draft118]=t.type==='number'?n(t.value):t.value});host.addEventListener('change',async e=>{const t=e.target;try{if(t.matches('[data-mode118]')){if(draft.data.lines.length&&!await ui117.confirm('Switch workspaces? Unsaved changes to the current order will be discarded.')){t.value=S.sample?'sample':'live';return}S.sample=t.value==='sample';localStorage.setItem('ojm_pos_mode119_'+liveProfile.id,S.sample?'sample':'live');S.loaded=false;S.orders=[];S.picked=null;S.selected=null;S.query='';S.category='All';S.filter='All';fresh();if(S.sample)samples();else await load();render()}else if(t.matches('[data-choice118]')){const key=t.dataset.choice118;S.choices[key]=t.type==='checkbox'?[...host.querySelectorAll('[data-choice118="'+CSS.escape(key)+'"]:checked')].map(n=>n.value):t.value?[t.value]:[];render()}else if(t.matches('[data-draft118]'))render();else if(t.matches('[data-receipt-date118]')){S.receiptDate=t.value;render()}}catch(e){showCenterStatus(e.message,true)}})}
